local a={}local function b(c,d,e)return math.max(d,math.min(e,c))end;function a:initScroll(f,g)self.scroll={pos_x=0,pos_y=0,max_x=0,max_y=0,sens_x=f or 3,sens_y=g or 3}self.scrollbar_v=nil;self.scrollbar_h=nil end;function a:getScrollMaxY()return self.scroll.max_y end;function a:getScrollPosY()return self.scroll.pos_y end;function a:setScrollPosY(h)local i=self.scroll.pos_y;self.scroll.pos_y=b(h,0,self:getScrollMaxY())if i~=self.scroll.pos_y then if self.scrollbar_h then self.scrollbar_h.dirty=true end;if self.scrollbar_v then self.scrollbar_v.dirty=true end;self:onLayout()return true end;return false end;function a:scrollY(j)local k=self.scroll.pos_y+j*self.scroll.sens_y;return self:setScrollPosY(math.floor(k+0.5))end;function a:getScrollMaxX()return self.scroll.max_x end;function a:getScrollPosX()return self.scroll.pos_x end;function a:setScrollPosX(h)local i=self.scroll.pos_x;self.scroll.pos_x=b(h,0,self:getScrollMaxX())if i~=self.scroll.pos_x then if self.scrollbar_h then self.scrollbar_h.dirty=true end;if self.scrollbar_v then self.scrollbar_v.dirty=true end;self:onLayout()return true end;return false end;function a:scrollX(j)local k=self.scroll.pos_x+j*self.scroll.sens_x;return self:setScrollPosX(math.floor(k+0.5))end;function a:getScrollMax()return self:getScrollMaxY()end;function a:getScrollPos()return self:getScrollPosY()end;function a:setScrollPos(h)return self:setScrollPosY(h)end;function a:attachScrollbar(l,m)if m=="horizontal"or m=="h"then self.scrollbar_h=l else self.scrollbar_v=l end end;function a.addMixin(n)for o,p in pairs(a)do n[o]=p end end;return a
